    $('#aJS', s).onclick = async () => { const x = need(); if (!x) return; const r = await App.form('Join spaziale', [{ name: 'b', label: 'Trasferisci attributi da (poligoni)', type: 'select', options: vecs.filter(v => v !== x).map(v => ({ value: v.id, label: v.name })) }]); if (!r) return; const B = layerById(r.b); let n = 0; x.features.forEach(ft => { const c = centroidLL(ft.geometry); const fb = B.features.find(f => polysOf(f.geometry).some(pl => G.pip(c, pl[0]))); if (fb) { n++; Object.entries(fb.properties).forEach(([k, v]) => ft.properties[k in ft.properties ? k + '_j' : k] = v); } }); App.touch(); renderTable(); App.toast(`Join spaziale: ${n} feature arricchite`, 'ok'); };
