  /** stampa tavola cartografica */
  async function printMap() {
    const r = await App.form('Stampa tavola cartografica', [{ name: 'title', label: 'Titolo', value: 'Inquadramento territoriale – ' + P.name }, { name: 'fmt', label: 'Formato', type: 'select', options: ['A4 orizzontale', 'A3 orizzontale'] }, { name: 'out', label: 'Uscita', type: 'select', options: ['GeoPDF (georiferito)', 'PNG'] }], 'Genera');
    if (!r) return; const mm = r.fmt.startsWith('A3') ? [420, 297] : [297, 210]; const pxmm = 5; const Wp = mm[0] * pxmm, Hp = mm[1] * pxmm; const c = document.createElement('canvas'); c.width = Wp; c.height = Hp; const x = c.getContext('2d');
    x.fillStyle = '#fff'; x.fillRect(0, 0, Wp, Hp); const mapW = Wp - 90 * pxmm, mapH = Hp - 30 * pxmm; const m0 = [10 * pxmm, 15 * pxmm];
    // render della mappa nella cornice
    const save = { W, H, ctx, dpr }; const mc = document.createElement('canvas'); mc.width = mapW; mc.height = mapH; W = mapW; H = mapH; dpr = 1; ctx = mc.getContext('2d'); const vres = view.res; view.res = view.res * (save.W / mapW); draw(); const ll0 = scrLL(0, H), ll1 = scrLL(W, 0); const resUsed = view.res; view.res = vres; W = save.W; H = save.H; ctx = save.ctx; dpr = save.dpr; draw();
    x.drawImage(mc, m0[0], m0[1]); x.strokeStyle = '#14213d'; x.lineWidth = 3; x.strokeRect(m0[0], m0[1], mapW, mapH);
    x.fillStyle = '#14213d'; x.font = `600 ${7 * pxmm}px Helvetica`; x.fillText(r.title, 10 * pxmm, 10 * pxmm);
    const lx = m0[0] + mapW + 8 * pxmm; let ly = m0[1] + 6 * pxmm; x.font = `600 ${4.5 * pxmm}px Helvetica`; x.fillText('Legenda', lx, ly); ly += 8 * pxmm; x.font = `${3.4 * pxmm}px Helvetica`;
    layers().filter(l => l.visible).forEach(l => { const st = l.style || {}; x.fillStyle = l.type === 'vector' ? hexA(st.fill || st.color, .5) : '#9ab'; x.strokeStyle = st.color || '#555'; x.lineWidth = 2; x.fillRect(lx, ly - 3.5 * pxmm, 8 * pxmm, 4.5 * pxmm); x.strokeRect(lx, ly - 3.5 * pxmm, 8 * pxmm, 4.5 * pxmm); x.fillStyle = '#14213d'; x.fillText(l.name.slice(0, 34), lx + 11 * pxmm, ly); ly += 7 * pxmm; });
    // nord e scala
    const nx = lx + 30 * pxmm, ny = Hp - 60 * pxmm; x.fillStyle = '#14213d'; x.beginPath(); x.moveTo(nx, ny - 12 * pxmm); x.lineTo(nx + 5 * pxmm, ny + 4 * pxmm); x.lineTo(nx, ny); x.lineTo(nx - 5 * pxmm, ny + 4 * pxmm); x.closePath(); x.fill(); x.font = `600 ${5 * pxmm}px Helvetica`; x.fillText('N', nx - 1.8 * pxmm, ny - 14 * pxmm);
    const lat = (ll0[1] + ll1[1]) / 2; const mpp = resUsed * Math.cos(lat * Math.PI / 180); const scaleDen = Math.round(mpp / (1 / pxmm / 1000)); x.font = `${3.5 * pxmm}px Helvetica`; x.fillText(`Scala 1:${scaleDen.toLocaleString('it-IT')} (${r.fmt.split(' ')[0]})`, lx, Hp - 40 * pxmm); const nice = [10, 20, 50, 100, 200, 500, 1000, 2000, 5000].find(n => n / mpp > 120) || 5000; x.fillRect(lx, Hp - 34 * pxmm, nice / mpp, 1.5 * pxmm); x.fillText(nice >= 1000 ? nice / 1000 + ' km' : nice + ' m', lx, Hp - 28 * pxmm);
    x.font = `${2.8 * pxmm}px Helvetica`; x.fillStyle = '#5d6879'; x.fillText(`Griglia WGS84 · CRS progetto ${P.crs} · ${new Date().toLocaleDateString('it-IT')}`, lx, Hp - 20 * pxmm); const att = [...new Set(layers().filter(l => l.visible).map(l => l.attribution || l.license).filter(Boolean))].join(' · '); x.fillText(('Fonti: ' + att).slice(0, 70), lx, Hp - 15 * pxmm); x.fillText(('© ' + App.state.org.name + ' – BeCity').slice(0, 60), lx, Hp - 10 * pxmm);
    // griglia geografica ai bordi
    x.font = `${2.6 * pxmm}px Helvetica`; x.fillStyle = '#14213d'; [0, .25, .5, .75, 1].forEach(t => { const lo = ll0[0] + (ll1[0] - ll0[0]) * t, la = ll0[1] + (ll1[1] - ll0[1]) * t; x.fillText(lo.toFixed(4) + '°', m0[0] + mapW * t - 6 * pxmm, m0[1] + mapH + 4 * pxmm); x.save(); x.translate(m0[0] - 2 * pxmm, m0[1] + mapH * (1 - t) + 6 * pxmm); x.rotate(-Math.PI / 2); x.fillText(la.toFixed(4) + '°', 0, 0); x.restore(); });
    if (r.out === 'PNG') { c.toBlob(b => App.download(App.slug(r.title) + '.png', b)); return; }
    const ptmm = 72 / 25.4; const jpg = App.pdf.dataURLtoBytes(c.toDataURL('image/jpeg', .9)); const Wpt = mm[0] * ptmm, Hpt = mm[1] * ptmm;
    const bx0 = m0[0] / pxmm * ptmm, by0 = (mm[1] - (m0[1] + mapH) / pxmm) * ptmm, bx1 = (m0[0] + mapW) / pxmm * ptmm, by1 = (mm[1] - m0[1] / pxmm) * ptmm;
    App.download(App.slug(r.title) + '_geo.pdf', App.pdf.make([{ w: Wpt, h: Hpt, content: `q ${Wpt.toFixed(2)} 0 0 ${Hpt.toFixed(2)} 0 0 cm /Im1 Do Q`, images: [{ name: 'Im1', data: jpg, w: Wp, h: Hp }], geo: { bbox: [bx0, by0, bx1, by1].map(v => +v.toFixed(2)), gpts: [ll0[1], ll0[0], ll1[1], ll0[0], ll1[1], ll1[0], ll0[1], ll1[0]] } }], { title: r.title }));
    App.toast('GeoPDF generato: il riquadro mappa è georiferito (WGS84)', 'ok');
  }
  async function search(q) {
    q = q.trim().toLowerCase(); if (!q) return; const res = [];
    GIS.PLACES.forEach(p => { if (p[0].toLowerCase().includes(q)) res.push({ t: `${p[0]} (${p[1]})`, go: () => GIS.zoomTo([p[3] - .03, p[2] - .02, p[3] + .03, p[2] + .02]) }); });
    const m = q.match(/(?:f(?:oglio)?\.?\s*(\d+))?.*?(?:p(?:art(?:icella)?)?\.?\s*(\d+))/);
    layers().filter(l => l.type === 'vector').forEach(l => l.features.forEach(f => { const pr = f.properties; const hitP = m && m[2] && String(pr.particella ?? pr.PARTICELLA ?? pr.part ?? '') === m[2] && (!m[1] || String(pr.foglio ?? pr.FOGLIO ?? '') === m[1]); if (hitP || Object.values(pr).some(v => String(v ?? '').toLowerCase() === q)) res.push({ t: `${l.name}: ${Object.entries(pr).slice(0, 3).map(([k, v]) => k + '=' + v).join(', ')}`, go: () => { active = l.id; selIds = new Set([f.id]); renderTree(); renderTable(); GIS.zoomTo(fBBox(f), 4); } }); }));
    const c = q.match(/^(-?\d+[.,]\d+)[\s,;]+(-?\d+[.,]\d+)$/); if (c) { const a = +c[1].replace(',', '.'), b = +c[2].replace(',', '.'); const [la, lo] = Math.abs(a) <= 90 && Math.abs(b) > 0 ? [a, b] : [b, a]; res.unshift({ t: `Coordinate ${la}, ${lo}`, go: () => GIS.zoomTo([lo - .002, la - .002, lo + .002, la + .002]) }); }
    if (!res.length) { App.toast('Nessun risultato (gazetteer offline: capoluoghi e attributi dei layer)', 'warn'); return; }
    if (res.length === 1) { res[0].go(); return; } const r = $('#gisSearch').getBoundingClientRect(); App.ctxMenu(r.left, r.bottom + 4, res.slice(0, 15).map(x => ({ label: App.esc(x.t), action: x.go })));
  }

